func worker(ctx context.Context, jobs <-chan Job) error {
	for {
		select {
		case <-ctx.Done():
			return ctx.Err()
		case j, ok := <-jobs:
			if !ok {
				return nil
			}
			if err := handle(ctx, j); err != nil {
				return err
			}
		}
	}
}

// stops waiting; the call keeps running and still costs you
select {
case v := <-done:
	use(v)
case <-time.After(2 * time.Second):
	return ErrTimeout
}

// stops the work: the HTTP request is actually aborted
ctx, cancel := context.WithTimeout(ctx, 2*time.Second)
defer cancel()
req, _ := http.NewRequestWithContext(ctx, "GET", url, nil)

var client = &http.Client{
	Timeout: 10 * time.Second,   // whole exchange, including the body
}
